# DOCX/TXT -> Text для ноды n8n "Code in Python (Beta)"
# Вход: items с binary.fileX (base64) и meta (fileName, mimeType)
# Выход: массив items с json.fileName и json.data (плоский текст)

import base64, io, zipfile, re
import xml.etree.ElementTree as ET

W_NS = {"w": "http://schemas.openxmlformats.org/wordprocessingml/2006/main"}

def b64_to_bytes(binfo: dict) -> bytes:
    return base64.b64decode(binfo.get("data", ""))

def decode_txt(raw: bytes) -> str:
    for enc in ("utf-8", "cp1251", "windows-1251", "latin-1"):
        try:
            return raw.decode(enc)
        except UnicodeDecodeError:
            continue
    return raw.decode("utf-8", errors="replace")

def docx_to_text(raw: bytes) -> str:
    # Чтение основного документа + минимальная обработка переносов, табов
    with zipfile.ZipFile(io.BytesIO(raw)) as z:
        xml = z.read("word/document.xml")
    root = ET.fromstring(xml)

    lines = []
    for p in root.findall(".//w:p", W_NS):
        parts = []
        # обрабатываем w:r/w:t и принудительные переносы w:br, табы w:tab
        for el in p.iter():
            tag = el.tag.split("}")[-1]
            if tag == "t":
                parts.append(el.text or "")
            elif tag == "tab":
                parts.append("\t")
            elif tag == "br":
                parts.append("\n")
        # убираем лишние пробелы внутри абзаца
        line = re.sub(r"[ \t]+\n", "\n", "".join(parts)).strip()
        lines.append(line)
    text = "\n".join(lines)
    # нормализация пустых строк
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()

def extract_text_from_binary(binfo: dict, name: str) -> str:
    raw = b64_to_bytes(binfo)
    lower = (name or "").lower()
    if lower.endswith(".docx"):
        return docx_to_text(raw)
    elif lower.endswith(".txt"):
        return decode_txt(raw)
    # попытка авто-детекта для неизвестных расширений
    try:
        return docx_to_text(raw)
    except Exception:
        return decode_txt(raw)

out_items = []

# !!! Главное: обращаться к item["binary"], а не item.binary
for item in items:
    bin_map = item.get("binary") or {}
    for key, binfo in bin_map.items():
        fname = binfo.get("fileName") or f"{key}.bin.txt"
        text = extract_text_from_binary(binfo, fname)
        out_items.append({"json": {"fileName": fname + ".txt" if not fname.endswith(".txt") else fname,
                                   "data": text}})

# Если нужно, чтобы downstream-ноды видели исходные items вместе с новыми — раскомментируй:
# if not out_items:
#     out_items = [{"json": {"fileName": "empty.txt", "data": ""}}]

return out_items

