// беру текст из $json.text или $json.templates.text
// const s = ($json.text ?? $json.templates?.text ?? '').toString();

// беру текст ответа от GPT из наиболее вероятных полей
const s = (
  $json.text ??
  $json.output ??
  $json.result ??
  $json.data ??
  ''
).toString();

// строки формата: {{key}}: value
const reKV = /^\s*\{\{\s*([A-Za-z0-9_]+)\s*\}\}:\s*(=?.+?)\s*$/;

// --- НОРМАЛИЗАТОРЫ РЕГИСТРА ---

const ABBRS = new Set([
  'BYN','ООО','ОАО','ЗАО','ИП','УНП','UNP','ID',
  'РУВД','РОВД','ОВД','МР' // серия паспорта/аббревиатуры
]);

// слова/предлоги, которые обычно пишем со строчной (в адресах/общем тексте)
const LOWER_WORDS = new Set([
  'и','в','во','на','но','за','по','из','к','ко','от','о','об','обо','при',
  'для','с','со','у','над','под','между','или','а','не'
]);



function smartCapWord(w, keepUpper=false) {
  if (!w) return w;

  // сохраняем верхний регистр ТОЛЬКО для явных аббревиатур из белого списка
  if (keepUpper || ABBRS.has(w)) return w;

  // числа/даты — не трогаем
  if (/^\d/.test(w)) return w;

  // инициалы: И. / И.О. -> капсом
  if (/^[A-Za-zА-Яа-яЁё]\.$/.test(w) || /^[A-Za-zА-Яа-яЁё]\.[A-Za-zА-Яа-яЁё]\.$/.test(w)) {
    return w.toUpperCase();
  }

  // дефисные слова — капитализируем каждую часть
  if (w.includes('-')) {
    return w.split('-').map(part => smartCapWord(part)).join('-');
  }

  // обычное слово: ПерваяБольшая ОстальныеМаленькие
  return w.slice(0,1).toUpperCase() + w.slice(1).toLowerCase();
}


// ФИО: каждую часть с заглавной, аббревиатуры сохраняем
function normalizeName(s) {
  return String(s)
    .split(/\s+/)
    .map(tok => smartCapWord(tok))
    .join(' ')
    .replace(/\s+/g,' ')
    .trim();
}



function normalizeAddress(s) {
  let t = String(s).trim();

  // унифицируем типовые обозначения в нижний регистр для служебных слов
  t = t
    .replace(/\bРЕСПУБЛИКА\s+БЕЛАРУСЬ\b/gi, 'Республика Беларусь') // собственные названия — с заглавной
    .replace(/\b(ГОРОД)\b/gi, 'город')
    .replace(/\b(ОБЛАСТЬ)\b/gi, 'область')
    .replace(/\b(РАЙОН|Р-Н)\b/gi, 'район')
    .replace(/\b(УЛИЦА)\b/gi, 'улица')
    .replace(/\b(ПРОСПЕКТ|ПР-Т)\b/gi, 'проспект')
    .replace(/\b(ПЕРЕУЛОК|ПЕР\.)\b/gi, 'переулок')
    .replace(/\b(Г\.)\b/gi, 'г.')
    .replace(/\b(ОБЛ\.)\b/gi, 'обл.')
    .replace(/\b(УЛ\.)\b/gi, 'ул.')
    .replace(/\b(ДОМ|Д\.)\b/gi, 'д.')
    .replace(/\b(КВАРТИРА|КВ\.)\b/gi, 'кв.');

  // токенизация + форматирование
  const tokens = t.split(/\s+/).map(tok => {
    // служебные маркеры — строго в нижнем регистре
    const m = tok.match(/^(город|область|район|р-н|улица|проспект|переулок|пер\.|г\.|обл\.|ул\.|д\.|кв\.)([,:;.]*)$/i);
    if (m) return m[1].toLowerCase() + m[2];
    // аббревиатуры (ООО, РУВД, BYN и т.п.) — оставляем капсом
    if (ABBRS.has(tok) || (/^[A-ZА-ЯЁ]{2,4}$/.test(tok) && !/\d/.test(tok))) {
      return tok.toUpperCase();
    }
    // числа/даты — как есть
    if (/^\d/.test(tok)) return tok;

    // мягкий тайтл-кейс для остальных слов (включая дефисные)
    return smartCapWord(tok);
  });

  // после служебных маркеров — следующему слову даём Заглавную (если это слово)
  const leadMarkers = /^(город|г\.|область|обл\.|район|р-н|улица|ул\.|проспект|переулок|пер\.)$/i;
  for (let i = 0; i < tokens.length - 1; i++) {
    if (leadMarkers.test(tokens[i]) && /^[A-Za-zА-Яа-яЁё-]+$/.test(tokens[i+1])) {
      tokens[i+1] = smartCapWord(tokens[i+1]);
    }
  }

  return tokens.join(' ').replace(/\s+/g, ' ').trim();
}


// Паспорт: «паспорт МР 000008 06.06.2000 Ленинским РОВД г. Минска»
function normalizePassport(s) {
  let t = String(s).trim();
  // МР/РУВД/РОВД/ОВД оставляем капсом
  t = t
    .replace(/\b(паспорт)\b/gi, 'паспорт')
    .replace(/\b(мр)\b/gi, 'МР')
    .replace(/\b(рувд)\b/gi, 'РУВД')
    .replace(/\b(ровд)\b/gi, 'РОВД')
    .replace(/\b(овд)\b/gi, 'ОВД')
    .replace(/\b(г\.)\b/gi, 'г.');

  // Остальное — мягкий тайтл-кейс
  t = t.split(/\s+/).map(tok => {
    if (ABBRS.has(tok) || /^[A-ZА-ЯЁ]{2,4}$/.test(tok)) return tok;
    if (/^\d+(\.\d+)*$/.test(tok)) return tok; // числа/даты
    if (tok.toLowerCase() === 'г.') return 'г.';
    return smartCapWord(tok);
  }).join(' ');

  return t.replace(/\s+/g,' ').trim();
}

// --- Основная логика разбора и нормализации ---

const NAME_KEYS = new Set(['PLAINTIFF_FULL','DEFENDANT_FULL']);
const ADDRESS_KEYS = new Set(['PLAINTIFF_ADDRESS','DEFENDANT_ADDRESS']);
const PASSPORT_KEYS = new Set(['DEFENDANT_PASSPORT','CLAIMANT_PASSPORT']);

const fields = {};

for (const line of s.replace(/\r\n/g, '\n').split('\n')) {
  const m = line.match(reKV);
  if (!m) continue;

  // ключ в ВЕРХНЕМ РЕГИСТРЕ (ключи нормализуем)
  const rawKey = m[1].trim();
  const keyUpper = rawKey.toUpperCase();
  const key = `{{${keyUpper}}}`;

  let val = m[2].trim();

  // --- Нормализация ЗНАЧЕНИЙ точечно по плейсхолдерам ---
  if (NAME_KEYS.has(keyUpper)) {
    val = normalizeName(val);
  } else if (ADDRESS_KEYS.has(keyUpper)) {
    val = normalizeAddress(val);
  } else if (PASSPORT_KEYS.has(keyUpper)) {
    val = normalizePassport(val);
  }
  // всё остальное (суммы, даты, e-mail и пр.) не трогаем

  fields[key] = val;
}

// опционально прокидываем шаблоны дальше по пайплайну
const out = { ...fields };
if ($json.template_opredelenie != null) out.template_opredelenie = $json.template_opredelenie;
if ($json.template_reshenie   != null) out.template_reshenie   = $json.template_reshenie;

return [{ json: out }];

