import math
from datetime import datetime, timedelta

# ---- helpers ----

def brace(k):
    """
    Оборачивает ключ в {{...}} и чистит пробелы / лишние скобки.
    """
    if not k:
        return k
    kk = str(k).strip()
    if kk.startswith("{{"):
        kk = kk.lstrip("{").lstrip("{").strip()
    if kk.endswith("}}"):
        kk = kk.rstrip("}").rstrip("}").strip()
    return "{{" + kk + "}}"


def get_s(map_, key):
    """
    Берёт строковое значение из map_:
    - сначала по ключу с {{...}}
    - потом по «сырому» ключу
    """
    b = brace(key)
    if b in map_:
        return str(map_[b]).strip()
    if key in map_:
        return str(map_[key]).strip()
    return ""


def parse_byn(s):
    """
    '1 234,56 BYN' -> 1234.56 (float), иначе NaN.
    """
    if not s:
        return math.nan
    clean = "".join(ch for ch in str(s) if ch.isdigit() or ch in ",.-")
    clean = clean.replace(",", ".")
    try:
        return float(clean)
    except ValueError:
        return math.nan


def format_byn(n):
    """
    float -> 'X.XX BYN' (NaN -> 0.00 BYN).
    """
    try:
        v = float(n)
    except (TypeError, ValueError):
        v = 0.0
    if not math.isfinite(v):
        v = 0.0
    return f"{v:.2f} BYN"


def parse_date_dmy(s):
    """
    'ДД.ММ.ГГГГ' -> datetime или None.
    """
    if not s:
        return None
    text = str(s).strip()
    try:
        return datetime.strptime(text, "%d.%m.%Y")
    except ValueError:
        return None


def to_dmy(d):
    """
    datetime -> 'ДД.ММ.ГГГГ'.
    """
    return d.strftime("%d.%m.%Y")


def date_add_days_dmy(dmy, days):
    """
    Дата 'ДД.ММ.ГГГГ' + days суток -> 'ДД.ММ.ГГГГ'.
    Если дата криво распарсилась, вернуть исходное или '___'.
    """
    d = parse_date_dmy(dmy)
    if not d:
        return dmy or "___"
    d = d + timedelta(days=days)
    return to_dmy(d)


def initials(full):
    """
    'Фамилия Имя Отчество' -> 'И.О. Фамилия'
    """
    if not full:
        return "___"
    parts = str(full).strip().split()
    if len(parts) < 2:
        return full
    last = parts[0]
    first = parts[1] if len(parts) >= 2 else ""
    middle = parts[2] if len(parts) >= 3 else ""
    i1 = (first[0].upper() + ".") if first else ""
    i2 = (middle[0].upper() + ".") if middle else ""
    return (i1 + i2 + " " + last).strip()


# ---- основная логика для всех items ----

new_items = []

for item in items:
    data = item.get("json", {}) or {}

    # соберём in_map с ключами в виде {{KEY}}
    in_map = {}
    for k, v in data.items():
        if isinstance(k, str):
            in_map[brace(k)] = v

    # входные строки
    loan_principal_s = get_s(in_map, "LOAN_PRINCIPAL")
    interest_sum_s   = get_s(in_map, "INTEREST_SUM")
    penalty_sum_s    = get_s(in_map, "PENALTY_SUM")

    # ОБРАТИ ВНИМАНИЕ: имена как в плейсхолдерах {{LOANDATE_START}} / {{LOANDATE_END}}
    loandate_start   = get_s(in_map, "LOANDATE_START")
    loandate_end     = get_s(in_map, "LOANDATE_END")

    claim_date       = get_s(in_map, "CLAIM_DATE")
    judge_full       = get_s(in_map, "JUDGE_FULL")

    # числа
    loan_principal_n = parse_byn(loan_principal_s)
    interest_sum_n   = parse_byn(interest_sum_s)
    penalty_sum_n    = parse_byn(penalty_sum_s)

    out = {}

    # {{PRINCIPAL_SUM}}
    if math.isfinite(loan_principal_n):
        out["{{PRINCIPAL_SUM}}"] = format_byn(loan_principal_n)
    else:
        out["{{PRINCIPAL_SUM}}"] = loan_principal_s or "___"

    # # {{INTEREST_FROM}} / {{INTEREST_TO}}
    # d_interest_from = parse_date_dmy(loandate_start)
    # out["{{INTEREST_FROM}}"] = to_dmy(d_interest_from) if d_interest_from else "___"
    # {{INTEREST_FROM}} / {{INTEREST_TO}}
    d_interest_from = parse_date_dmy(loandate_start)
    out["{{INTEREST_FROM}}"] = to_dmy(d_interest_from) if d_interest_from else "___"

    d_interest_to = parse_date_dmy(loandate_end)
    out["{{INTEREST_TO}}"] = to_dmy(d_interest_to) if d_interest_to else "___"


    # # {{TOTAL_SUM}} = principal + interest + penalty
    # if all(math.isfinite(x) for x in (loan_principal_n, interest_sum_n, penalty_sum_n)):
    #     total_sum_n = loan_principal_n + interest_sum_n + penalty_sum_n
    #     out["{{TOTAL_SUM}}"] = format_byn(total_sum_n)
    # else:
    #     out["{{TOTAL_SUM}}"] = "___"


    # {{PENALTY_FROM}} = следующий день после окончания займа
    if loandate_end:
        out["{{PENALTY_FROM}}"] = date_add_days_dmy(loandate_end, 1)
    else:
        out["{{PENALTY_FROM}}"] = "___"


    # {{PENALTY_TO}} = дата подачи иска
    d_claim = parse_date_dmy(claim_date)
    out["{{PENALTY_TO}}"] = to_dmy(d_claim) if d_claim else "___"

    # d_interest_to = parse_date_dmy(loandate_end)
    # out["{{INTEREST_TO}}"] = to_dmy(d_interest_to) if d_interest_to else "___"

    # # {{TOTAL_SUM}} = principal + interest + penalty
    # if all(math.isfinite(x) for x in (loan_principal_n, interest_sum_n, penalty_sum_n)):
    #     total_sum_n = loan_principal_n + interest_sum_n + penalty_sum_n
    #     out["{{TOTAL_SUM}}"] = format_byn(total_sum_n)
    # else:
    #     out["{{TOTAL_SUM}}"] = "___"

    # # {{PENALTY_FROM}} = день после LOANDATE_END
    # if loandate_end:
    #     out["{{PENALTY_FROM}}"] = date_add_days_dmy(loandate_end, 1)
    # else:
    #     out["{{PENALTY_FROM}}"] = "___"

    # # {{PENALTY_TO}} = CLAIM_DATE в ДД.ММ.ГГГГ
    # d_claim = parse_date_dmy(claim_date)
    # out["{{PENALTY_TO}}"] = to_dmy(d_claim) if d_claim else "___"

    # {{JUDGE_INITIALS}}
    out["{{JUDGE_INITIALS}}"] = initials(judge_full)

    new_items.append({"json": out})

# результат ноды
return new_items

