const orig = $node["Prepare messages1"].json._orig ?? {};

// HTTP Request response is current $json
const proxyResponse = { ...$json };

// Try to extract assistant text from common OpenAI-like shapes
let text = "";
if (proxyResponse?.choices?.[0]?.message?.content) {
  text = String(proxyResponse.choices[0].message.content);
} else if (typeof proxyResponse.body === "string") {
  text = proxyResponse.body;
} else if (proxyResponse.body?.choices?.[0]?.message?.content) {
  text = String(proxyResponse.body.choices[0].message.content);
} else if (typeof proxyResponse.text === "string") {
  text = proxyResponse.text;
} else if (typeof proxyResponse.data === "string") {
  text = proxyResponse.data;
} else if (proxyResponse.data?.choices?.[0]?.message?.content) {
  text = String(proxyResponse.data.choices[0].message.content);
}

